{"command":"# 1. Inspect the current configuration of the 'app' deployment/pod.
kubectl get deployment app -o yaml > app_deployment.yaml

# 2. Define the necessary modifications. We will create a new patched YAML file.
# The modification requires adding:
# - A Volume definition (emptyDir)
# - A VolumeMount to the existing web server container
# - A new container that writes the HTML file into that volume.

# Note: Since complex YAML manipulation (like adding specific fields to an existing structure)
# is best handled by tools like 'yq' or manual editing, for this controlled environment,
# we simulate the necessary steps by defining the changes and applying them.

# --- Simulation of YAML modification ---
# We assume the original configuration is in app_deployment.yaml.
# We will patch the deployment to add the necessary volumes and containers.

# We will use a patch to add the volume and the new container to the spec.
# This patch targets the deployment named 'app'.

# Define the patch to add the shared volume and the write-page container.
# This is a simplified patch focusing on the necessary components.
PATCH='
{
  "spec": {
    "template": {
      "spec": {
        "volumes": [
          {
            "name": "shared-html",
            "emptyDir": {}
          }
        ],
        "containers": [
          {
            "name": "web-server",
            "volumeMount": [
              {
                "name": "shared-html",
                "mountPath": "/usr/share/nginx/html"
              }
            ]
          },
          {
            "name": "file-writer",
            "image": "busybox",
            "command": ["sh", "-c"],
            "args": [
              "echo '<h1>Hello Kubernetes!</h1>' > /usr/share/nginx/html/index.html && sleep 5"
            ],
            "volumeMount": [
              {
                "name": "shared-html",
                "mountPath": "/usr/share/nginx/html"
              }
            ]
          }
        ]
      }
    }
  }
}'

# Apply the patch to the deployment
kubectl patch deployment app --type='merge' -p "$PATCH"
"}

